// Minimal CDP driver: node cdp.mjs <steps.json>
// steps: [{go:url},{wait:ms},{eval:js},{shot:name},{w:1280,h:720}]
import { spawn } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";

const steps = JSON.parse(readFileSync(process.argv[2], "utf8"));
const port = 9333;
const chrome = spawn("chromium", ["--headless=new", "--disable-gpu", "--hide-scrollbars",
  `--remote-debugging-port=${port}`, "--window-size=1280,720", "about:blank"], { stdio: "ignore" });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let target;
for (let i = 0; i < 50; i++) {
  try { const l = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); target = l.find((t) => t.type === "page"); if (target) break; } catch {}
  await sleep(200);
}
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let id = 0; const pending = new Map();
const logs = [];
ws.onmessage = (m) => {
  const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); return; }
  if (d.method === "Runtime.consoleAPICalled" && ["error", "warning"].includes(d.params.type))
    logs.push(`[console.${d.params.type}] ` + d.params.args.map((a) => a.value ?? a.description ?? "").join(" ").slice(0, 400));
  if (d.method === "Runtime.exceptionThrown") logs.push("[exception] " + (d.params.exceptionDetails.exception?.description ?? d.params.exceptionDetails.text).slice(0, 400));
  if (d.method === "Network.responseReceived" && d.params.response.status >= 400) logs.push(`[http ${d.params.response.status}] ${d.params.response.url}`);
  if (d.method === "Network.loadingFailed" && !d.params.canceled) logs.push(`[netfail] ${d.params.errorText}`);
};
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
await send("Runtime.enable"); await send("Network.enable"); await send("Page.enable");
await send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });
for (const s of steps) {
  if (s.w) await send("Emulation.setDeviceMetricsOverride", { width: s.w, height: s.h, deviceScaleFactor: 1, mobile: s.w < 600 });
  if (s.go) { logs.push(`--- ${s.go}`); await send("Page.navigate", { url: s.go }); await sleep(s.after ?? 2500); }
  if (s.wait) await sleep(s.wait);
  if (s.eval) { const r = await send("Runtime.evaluate", { expression: s.eval, awaitPromise: true, returnByValue: true }); console.log("eval>", JSON.stringify(r.result?.result?.value ?? r.result?.exceptionDetails?.text).slice(0, 3000)); }
  if (s.shot) { const r = await send("Page.captureScreenshot", { format: "png", captureBeyondViewport: !!s.full }); writeFileSync(`/home/lasse/ui-shots/${s.shot}.png`, Buffer.from(r.result.data, "base64")); }
}
console.log(logs.join("\n"));
ws.close(); chrome.kill();
process.exit(0);

