import type { Metadata } from "next";
import { Hanken_Grotesk } from "next/font/google";
import "./globals.css";
import { ShellFrame } from "@/src/components/shell/ShellFrame";

// BMW Type Next ist proprietär, Hanken Grotesk ist die freie, ähnlich geometrische Alternative.
const hanken = Hanken_Grotesk({
  variable: "--font-hanken",
  subsets: ["latin"],
  weight: ["200", "300", "400", "500", "600", "700"],
});

export const metadata: Metadata = {
  title: "Signal2Spec",
  description: "From customer voice to the next BMW. Evidence-backed product requirements for PM decisions.",
  openGraph: {
    title: "Signal2Spec",
    description: "From customer voice to the next BMW.",
    type: "website",
  },
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={`${hanken.variable} antialiased`} suppressHydrationWarning>
      <body className="min-h-screen" suppressHydrationWarning>
        <ShellFrame>{children}</ShellFrame>
      </body>
    </html>
  );
}
@import "tailwindcss";

/* BMW-nahe Design-Tokens. Warum als CSS-Variablen: ein Ort für die Farben,
   Komponenten und die Tailwind-Klassen der Unterseiten ziehen alle daraus. */
:root {
  --blue: #1c69d4;
  --blue-hover: #0653b6;
  --ink: #262626;
  --black: #0a0a0b;
  --grey-100: #f6f6f6;
  --grey-500: #6b6b6b;
  --hairline: #e6e6e6;
  --m-light: #81c4ff;
  --m-dark: #16588e;
  --m-red: #e22718;
  --background: #ffffff;
  --foreground: var(--ink);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-hanken), system-ui, sans-serif;
}

/* Die Unterseiten (Overview, Audit, Detail) nutzen noch Tailwind-Klassen
   wie slate/blue/rounded/shadow. Statt 40 Dateien umzuschreiben, biegen wir
   die Tailwind-Skalen auf die BMW-Sprache um: neutrales Grau, BMW-Blau,
   0 px Radius, keine Schatten. */
@theme {
  --color-slate-50: #f6f6f6;
  --color-slate-100: #f0f0f0;
  --color-slate-200: #e6e6e6;
  --color-slate-300: #cfcfcf;
  --color-slate-400: #9a9a9a;
  --color-slate-500: #6b6b6b;
  --color-slate-600: #4d4d4d;
  --color-slate-700: #333333;
  --color-slate-800: #262626;
  --color-slate-900: #0a0a0b;
  --color-blue-50: #eef4fc;
  --color-blue-100: #dce8f9;
  --color-blue-200: #bcd3f2;
  --color-blue-300: #8fb4e8;
  --color-blue-600: #1c69d4;
  --color-blue-700: #0653b6;
  --color-blue-800: #0a4496;
  --color-blue-900: #0a2f66;
  /* One corner rule: everything square like buttons, logo and table chips; only status dots stay round. */
  --radius-xs: 0;
  --radius-sm: 0;
  --radius-md: 0;
  --radius-lg: 0;
  --radius-xl: 0;
  --radius-2xl: 0;
  --shadow-xs: none;
  --shadow-sm: none;
  --shadow-md: none;
  --shadow-lg: none;
}

* {
  box-sizing: border-box;
  letter-spacing: 0 !important;
}

.field-label { display: grid; gap: 6px; min-width: 0; font-size: 12px; font-weight: 600; color: var(--grey-500); }
.field-control { min-height: 44px; width: 100%; min-width: 0; border: 1px solid var(--hairline); border-radius: 0; padding: 8px 12px; background: white; color: var(--ink); font-size: 14px; font-weight: 400; }
button:not(:disabled), summary, select { cursor: pointer; }
